1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Normalises the city of a newly created owner. The city is title-cased (e.g.
9	 * {@code "san francisco"} becomes {@code "San Francisco"}) so the value stored and
10	 * returned is consistently capitalised. However, if any owner already lives in that
11	 * city (matched case- and whitespace-insensitively), that owner's exact spelling of the
12	 * city name is reused instead, so a city is spelt the same way across all its owners.
13	 */
14	public class NormalizeCity {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        String city = owner.getCity();
18	        if (city == null) {
19	            return;
20	        }
21	        for (Owner existing : ownerRepository.findAll()) {
22	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
23	                continue;
24	            }
25	            if (DuplicateMatching.matches(existing.getCity(), city)) {
26	                owner.setCity(existing.getCity());
27	                return;
28	            }
29	        }
30	        owner.setCity(titleCase(city));
31	    }
32	
33	    /**
34	     * Title-cases a city name: the first letter of each word is upper-cased and the rest
35	     * lower-cased, where words are separated by any non-letter character (so both
36	     * {@code "new york"} and {@code "winston-salem"} are handled). Surrounding and
37	     * repeated whitespace is collapsed. {@code null} stays {@code null}.
38	     */
39	    static String titleCase(String city) {
40	        if (city == null) {
41	            return null;
42	        }
43	        String collapsed = city.trim().replaceAll("\\s+", " ");
44	        StringBuilder result = new StringBuilder(collapsed.length());
45	        boolean startOfWord = true;
46	        for (int i = 0; i < collapsed.length(); i++) {
47	            char c = collapsed.charAt(i);
48	            if (Character.isLetter(c)) {
49	                result.append(startOfWord ? Character.toTitleCase(c) : Character.toLowerCase(c));
50	                startOfWord = false;
51	            } else {
52	                result.append(c);
53	                startOfWord = true;
54	            }
55	        }
56	        return result.toString();
57	    }
58	}
