3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.OwnerCityLimitException;
7	
8	/**
9	 * Rejects creating an owner once {@value #CITY_LIMIT} owners already live in the owner's
10	 * city (matched case- and whitespace-insensitively), by throwing an
11	 * {@link OwnerCityLimitException}, handled as 400.
12	 */
13	public class RejectOwnerCityLimit {
14	
15	    static final int CITY_LIMIT = 8;
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws OwnerCityLimitException {
18	        if (owner.getCity() == null) {
19	            return;
20	        }
21	        long cityCount = 0;
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
24	                continue;
25	            }
26	            if (DuplicateMatching.matches(existing.getCity(), owner.getCity())) {
27	                cityCount++;
28	            }
29	        }
30	        if (cityCount >= CITY_LIMIT) {
31	            throw new OwnerCityLimitException(
32	                "The maximum number of owners for this city has already been reached");
33	        }
34	    }
35	}
