3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;
7	
8	/**
9	 * Rejects creating an owner whose telephone number is already used by any other owner, by
10	 * throwing a {@link DuplicateOwnerException}, handled as 409.
11	 */
12	public class RejectDuplicateOwner {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) throws DuplicateOwnerException {
15	        if (owner.getTelephone() == null) {
16	            return;
17	        }
18	        for (Owner existing : ownerRepository.findAll()) {
19	            if (isSameOwner(existing, owner)) {
20	                continue;
21	            }
22	            if (DuplicateMatching.matches(existing.getTelephone(), owner.getTelephone())) {
23	                throw new DuplicateOwnerException(
24	                    "An owner with the same telephone number already exists");
25	            }
26	        }
27	    }
28	
29	    private static boolean isSameOwner(Owner existing, Owner candidate) {
30	        return existing.getId() != null && existing.getId().equals(candidate.getId());
31	    }
32	}
