1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns a customer code to a newly created owner, formatted
9	 * '&lt;UPPERCASE_CITY&gt;-&lt;NNNN&gt;' where NNNN is one more than the number of
10	 * owners already in that city, zero-padded to four digits (e.g. 'LONDON-0007').
11	 * The owner being created has not yet been saved, so it is not counted.
12	 */
13	public class AssignCustomerCode {
14	
15	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
16	        String city = owner.getCity();
17	        long inCity = ownerRepository.findAll().stream()
18	                .filter(existing -> city != null && city.equals(existing.getCity()))
19	                .count();
20	        String prefix = city == null ? "" : city.toUpperCase();
21	        owner.setCustomerCode(String.format("%s-%04d", prefix, inCity + 1));
22	    }
23	}
