7	/**
8	 * Assigns a membership tier to a newly created owner: the first 100 owners ever
9	 * created are 'FOUNDING' and all later owners are 'STANDARD'. The owner being
10	 * created has not yet been saved, so it is not counted; it is the
11	 * (existing + 1)th owner ever created.
12	 */
13	public class AssignMembershipTier {
14	
15	    static final int FOUNDING_LIMIT = 100;
16	
17	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
18	        long everCreated = ownerRepository.findAll().size() + 1;
19	        owner.setMembershipTier(everCreated <= FOUNDING_LIMIT ? "FOUNDING" : "STANDARD");
20	    }
21	}
