9	 * that already share the same last name at the moment of creation. The owner being
10	 * created has not yet been saved, so it is not counted among its own namesakes.
11	 */
12	public class AssignNamesakeCount {
13	
14	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
15	        String lastName = owner.getLastName();
16	        long count = ownerRepository.findAll().stream()
17	                .filter(existing -> lastName == null ? existing.getLastName() == null
18	                        : lastName.equals(existing.getLastName()))
19	                .count();
20	        owner.setNamesakeCount((int) count);
21	    }
