3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the household-sharing flag to a newly created owner: {@code true} if another
9	 * owner already had the same address and city at the moment of creation, otherwise
10	 * {@code false}. The owner being created has not yet been saved, so it never matches
11	 * itself. Address and city are matched case- and whitespace-insensitively, consistent
12	 * with the other owner uniqueness rules.
13	 */
14	public class AssignSharesHousehold {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        boolean shares = false;
18	        for (Owner existing : ownerRepository.findAll()) {
19	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
20	                continue;
21	            }
22	            if (DuplicateMatching.matches(existing.getAddress(), owner.getAddress())
23	                    && DuplicateMatching.matches(existing.getCity(), owner.getCity())) {
24	                shares = true;
25	                break;
26	            }
27	        }
28	        owner.setSharesHousehold(shares);
29	    }
30	}
