1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.HashMap;
4	import java.util.Map;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Assigns the locality of a newly created owner: {@code "local"} if the owner's city is
12	 * the single most common city among existing owners at the moment of creation, otherwise
13	 * {@code "remote"}. The owner being created has not yet been saved, so it is not counted.
14	 * If no owner exists yet, or several cities tie for the most common, there is no single
15	 * most common city and the owner is {@code "remote"}. Cities are grouped case- and
16	 * whitespace-insensitively, consistent with the other owner rules.
17	 */
18	public class AssignLocality {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        Map<String, Integer> counts = new HashMap<>();
22	        for (Owner existing : ownerRepository.findAll()) {
23	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
24	                continue;
25	            }
26	            String key = DuplicateMatching.normalize(existing.getCity());
27	            if (key == null) {
28	                continue;
29	            }
30	            counts.merge(key, 1, Integer::sum);
31	        }
32	
33	        int max = 0;
34	        int tally = 0;
35	        String topCity = null;
36	        for (Map.Entry<String, Integer> entry : counts.entrySet()) {
37	            int count = entry.getValue();
38	            if (count > max) {
39	                max = count;
40	                tally = 1;
41	                topCity = entry.getKey();
42	            } else if (count == max) {
43	                tally++;
44	            }
45	        }
46	
47	        boolean single = tally == 1 && topCity != null;
48	        boolean local = single && topCity.equals(DuplicateMatching.normalize(owner.getCity()));
49	        owner.setLocality(local ? "local" : "remote");
50	    }
51	}
