3	import java.util.Locale;
4	import java.util.Objects;
5	
6	/**
7	 * Shared value matching for owner duplicate detection. Comparisons ignore letter case
8	 * and surrounding or repeated whitespace, so {@code "  john   smith "} and
9	 * {@code "John Smith"} are treated as the same value.
10	 */
11	final class DuplicateMatching {
12	
13	    private DuplicateMatching() {
14	    }
15	
16	    /**
17	     * Normalises a value for duplicate comparison: trims, collapses any run of
18	     * whitespace to a single space and lower-cases. {@code null} stays {@code null}.
19	     */
20	    static String normalize(String value) {
21	        if (value == null) {
22	            return null;
23	        }
24	        String collapsed = value.trim().replaceAll("\\s+", " ");
25	        return collapsed.toLowerCase(Locale.ROOT);
26	    }
27	
28	    /**
29	     * Whether two values are the same once normalised (case- and whitespace-insensitive).
30	     */
31	    static boolean matches(String a, String b) {
32	        return Objects.equals(normalize(a), normalize(b));
33	    }
34	}
