3	/**
4	 * Normalises telephone numbers to digits only, stripping spaces, dashes and
5	 * parentheses (and any other non-digit formatting). This is applied before an owner is
6	 * stored and before the telephone-uniqueness check, so {@code "(613) 555-0100"} and
7	 * {@code "6135550100"} are treated as the same number.
8	 */
9	final class TelephoneNormalizer {
10	
11	    private TelephoneNormalizer() {
12	    }
13	
14	    /**
15	     * Returns the telephone with all non-digit characters removed. {@code null} stays
16	     * {@code null}.
17	     */
18	    static String digitsOnly(String telephone) {
19	        if (telephone == null) {
20	            return null;
21	        }
22	        return telephone.replaceAll("\\D", "");
23	    }
24	}
